import sys
lines = sys.stdin.readlines()
n = int(lines[0].strip())
edges = {}
for i in range(1, n):
	(u, v) = map(int, lines[i].strip().split(' '))
	if u not in edges:
		edges[u] = []
	if v not in edges:
		edges[v] = []
	edges[u].append(v)
	edges[v].append(u)
leaves = []
parLeave = {}
for u in edges.keys():
	if len(edges[u]) == 1:
		leaves.append(u)
		parLeave[u] = edges[u][0]
maxF = n - (len(leaves) - len(set(parLeave.values()))) - 1
parity = {leaves[0]: 0}
stack = [leaves[0]]
seen = set(stack)
while stack:
	node = stack.pop()
	for adj in edges[node]:
		if adj not in seen:
			parity[adj] = 1 - parity[node]
			stack.append(adj)
			seen.add(adj)
parityOfLeaves = list(map(lambda x: parity[x], leaves))
if min(parityOfLeaves) == max(parityOfLeaves):
	minF = 1
else:
	minF = 3
print('{} {}'.format(minF, maxF))
